    row_sums = [1, 11, 7, 16, 9, 25, 3, 5, 6]
    col_sums = [9, 6, 7, 14, 8, 17, 7, 6, 9]
    n = 9

    # Pre-calculate possible combinations for each row sum
    def get_combinations(target, n):
        results = []
        def backtrack(idx, current_sum, current_comb):
            if idx == n:
                if current_sum == target:
                    results.append(list(current_comb))
                return
            # Option 0
            current_comb.append(0)
            backtrack(idx + 1, current_sum, current_comb)
            current_comb.pop()
            # Option 1
            if current_sum + (idx + 1) <= target:
                current_comb.append(1)
                backtrack(idx + 1, current_sum + (idx + 1), current_comb)
                current_comb.pop()

        backtrack(0, 0, [])
        return results

    row_options = [get_combinations(rs, n) for rs in row_sums]

    grid = [None] * n
    current_col_sums = [0] * n

    def solve(row_idx):
        if row_idx == n:
            if all(current_col_sums[j] == col_sums[j] for j in range(n)):
                return True
            return False

        for opt in row_options[row_idx]:
            # Check if this row option is compatible with column constraints
            valid = True
            for j in range(n):
                new_col_sum = current_col_sums[j] + opt[j] * (row_idx + 1)
                if new_col_sum > col_sums[j]:
                    valid = False
                    break
                # Heuristic: if remaining rows can't reach the target col sum
                remaining_max = sum(k + 1 for k in range(row_idx + 1, n))
                if new_col_sum + remaining_max < col_sums[j]:
                    valid = False
                    break

            if valid:
                grid[row_idx] = opt
                for j in range(n):
                    current_col_sums[j] += opt[j] * (row_idx + 1)
                if solve(row_idx + 1):
                    return True
                for j in range(n):
                    current_col_sums[j] -= opt[j] * (row_idx + 1)
        return False

    if solve(0):
        return grid
    return None

solution = solve_kukurasu()
